package development_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/development"
	"github.com/stretchr/testify/require"
)

func TestEnum_ESTIMATOR_SENSOR_FUSION_SOURCE(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.ESTIMATOR_SENSOR_FUSION_SOURCE
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.ESTIMATOR_SENSOR_FUSION_SOURCE_GPS.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.ESTIMATOR_SENSOR_FUSION_SOURCE
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.ESTIMATOR_SENSOR_FUSION_SOURCE_GPS, dec)
	})
}
